      const validDate=typeof x.actionDate==="string"&&/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(x.actionDate);
      const validSource=typeof x.sourceUrl==="string"&&(x.sourceUrl===""||x.sourceUrl.startsWith("https://"));
