      return{id:x.id,symbol:x.symbol.trim().toUpperCase(),kind:x.kind as "cash_dividend"|"bonus_share"|"rights_share",actionDate:x.actionDate as string,cashReceived:x.cashReceived,sharesCredited:x.sharesCredited,note:x.note,sourceUrl:x.sourceUrl as string};
